}

exercises.solution:
function grammySummary(artists) {
  return artists.map(a => ({
    name: a.name,
    wins: a.grammyWins,
    nominations: a.grammyNominations,
    winRate: a.grammyNominations > 0 ? Math.round((a.grammyWins / a.grammyNominations) * 100) / 100 : 0
  }));
}

