 * @param {Object[]} albums - Array of album objects
 * @returns {string[]} Unique featured artist names
 */
function getFeaturedArtists(albums) {

}

exercises.solution:
function getFeaturedArtists(albums) {
  const allFeatures = albums.flatMap(album => album.tracks.flatMap(track => track.features));
  return [...new Set(allFeatures)];
}

