- `avgMetacritic`: average Metacritic score (rounded to 1 decimal)
- `platforms`: sorted array of unique platform names across all their games

Example:
```
developerPortfolio(platforms, games)
// Returns: {
//   "Rockstar Lames": { games: ["Red Fed Redemption 2", "Grand Theft Avocado V"], totalPlayers: 265000000, avgMetacritic: 97, platforms: ["GameStation 4", "GameStation 5", "PC", "X-Bocks One", "X-Bocks Series X"] },
//   ...
// }
```

exercises.solution:
function developerPortfolio(platforms, games) {
  const result = {};
  games.forEach(game => {
    const dev = game.developer;
    if (!result[dev]) result[dev] = { games: [], totalPlayers: 0, totalMeta: 0, platformIds: new Set() };
    result[dev].games.push(game.title);
    result[dev].totalPlayers += game.players.total;
    result[dev].totalMeta += game.ratings.metacritic;
    game.platformIds.forEach(pid => result[dev].platformIds.add(pid));
  });
  Object.keys(result).forEach(dev => {
    const entry = result[dev];
    entry.avgMetacritic = Math.round((entry.totalMeta / entry.games.length) * 10) / 10;
    entry.platforms = platforms
      .filter(p => entry.platformIds.has(p.id))
      .map(p => p.name)
      .sort();
    delete entry.totalMeta;
    delete entry.platformIds;
  });
  return result;
}

