exercises.solution:
function getBaseTotals(pokemon) {
  return pokemon.map(p => ({
    name: p.name,
    bst: p.stats.hp + p.stats.attack + p.stats.defense + p.stats.spAttack + p.stats.spDefense + p.stats.speed
  })).sort((a, b) => b.bst - a.bst);
}

