/**
 * @param {Object[]} types - Array of type objects
 * @param {Object[]} pokemon - Array of Pokemans objects
 * @param {string} name - Pokemans name
 * @returns {string[]} Sorted unique types the Pokemans is strong against
 */
function getAdvantages(types, pokemon, name) {

}

exercises.solution:
function getAdvantages(types, pokemon, name) {
  const mon = pokemon.find(p => p.name === name);
  if (!mon) return [];
  const advantages = mon.types.flatMap(typeName => {
    const typeData = types.find(t => t.name === typeName);
    return typeData ? typeData.strongAgainst : [];
  });
  return [...new Set(advantages)].sort();
}

