/**
 * @param {Object[]} pokemon - Array of Pokemans objects
 * @param {string} type - Type to search for
 * @returns {string|null} Name of fastest Pokemans of that type
 */
function fastestOfType(pokemon, type) {

}

exercises.solution:
function fastestOfType(pokemon, type) {
  const ofType = pokemon.filter(p => p.types.includes(type));
  if (ofType.length === 0) return null;
  return ofType.reduce((fastest, p) => p.stats.speed > fastest.stats.speed ? p : fastest).name;
}

