/**
 * @param {Object[]} pokemon - Array of Pokemans objects
 * @returns {Object[]} Pokemans that can evolve, sorted by name
 */
function canEvolve(pokemon) {

}

exercises.solution:
function canEvolve(pokemon) {
  return pokemon
    .filter(p => p.evolution.to !== null)
    .map(p => ({ name: p.name, evolvesTo: p.evolution.to, method: p.evolution.method }))
    .sort((a, b) => a.name.localeCompare(b.name));
}

