exercises.starterCode:
/**
 * @param {Object[]} pokemon - Array of Pokemans objects
 * @param {string} type - Type to filter by
 * @returns {Object|null} Average stats object or null
 */
function avgStatsByType(pokemon, type) {

}

exercises.solution:
function avgStatsByType(pokemon, type) {
  const ofType = pokemon.filter(p => p.types.includes(type));
  if (ofType.length === 0) return null;
  const len = ofType.length;
  return {
    hp: Math.round(ofType.reduce((s, p) => s + p.stats.hp, 0) / len * 10) / 10,
    attack: Math.round(ofType.reduce((s, p) => s + p.stats.attack, 0) / len * 10) / 10,
    defense: Math.round(ofType.reduce((s, p) => s + p.stats.defense, 0) / len * 10) / 10,
    spAttack: Math.round(ofType.reduce((s, p) => s + p.stats.spAttack, 0) / len * 10) / 10,
    spDefense: Math.round(ofType.reduce((s, p) => s + p.stats.spDefense, 0) / len * 10) / 10,
    speed: Math.round(ofType.reduce((s, p) => s + p.stats.speed, 0) / len * 10) / 10
  };
}

