exercises.solution:
function typeCoverage(types, pokemon) {
  return pokemon.map(p => {
    const strong = [...new Set(p.types.flatMap(tn => {
      const td = types.find(t => t.name === tn);
      return td ? td.strongAgainst : [];
    }))].sort();
    const weak = [...new Set(p.types.flatMap(tn => {
      const td = types.find(t => t.name === tn);
      return td ? td.weakAgainst : [];
    }))].sort();
    return {
      name: p.name,
      types: p.types,
      strongAgainst: strong,
      weakAgainst: weak,
      coverageScore: strong.length - weak.length
    };
  }).sort((a, b) => b.coverageScore - a.coverageScore);
}

