exercises.solution:
function generationSummary(pokemon) {
  const result = {};
  pokemon.forEach(p => {
    const gen = p.generation;
    if (!result[gen]) result[gen] = { count: 0, totalBST: 0, typeSet: new Set(), legendaryCount: 0 };
    result[gen].count++;
    result[gen].totalBST += p.stats.hp + p.stats.attack + p.stats.defense + p.stats.spAttack + p.stats.spDefense + p.stats.speed;
    p.types.forEach(t => result[gen].typeSet.add(t));
    if (p.isLegendary) result[gen].legendaryCount++;
  });
  Object.keys(result).forEach(gen => {
    result[gen].avgBST = Math.round(result[gen].totalBST / result[gen].count);
    result[gen].types = [...result[gen].typeSet].sort();
    delete result[gen].totalBST;
    delete result[gen].typeSet;
  });
  return result;
}

