exercises.solution:
function analyzeTeam(types, pokemon, teamNames) {
  const team = teamNames.map(name => pokemon.find(p => p.name === name)).filter(Boolean);
  const members = team.map(p => ({ name: p.name, types: p.types }));
  const totalBST = team.reduce((sum, p) => sum + p.stats.hp + p.stats.attack + p.stats.defense + p.stats.spAttack + p.stats.spDefense + p.stats.speed, 0);
  const typesCovered = [...new Set(team.flatMap(p => p.types.flatMap(tn => {
    const td = types.find(t => t.name === tn);
    return td ? td.strongAgainst : [];
  })))].sort();
  const weaknesses = [...new Set(team.flatMap(p => p.types.flatMap(tn => {
    const td = types.find(t => t.name === tn);
    return td ? td.weakAgainst : [];
  })))].sort();
  const allTypeNames = types.map(t => t.name);
  const uncoveredTypes = allTypeNames.filter(t => !typesCovered.includes(t)).sort();
  return { members, totalBST, typesCovered, weaknesses, uncoveredTypes };
}

