exercises.solution:
function pokedexAnalysis(types, pokemon) {
  const legendaryCount = pokemon.filter(p => p.isLegendary).length;
  const avgCatchRate = Math.round(pokemon.reduce((s, p) => s + p.catchRate, 0) / pokemon.length * 10) / 10;
  const heaviest = pokemon.reduce((h, p) => p.weight > h.weight ? p : h);
  const tallest = pokemon.reduce((t, p) => p.height > t.height ? p : t);
  const typeDistribution = {};
  pokemon.forEach(p => p.types.forEach(t => { typeDistribution[t] = (typeDistribution[t] || 0) + 1; }));
  return {
    totalPokemon: pokemon.length,
    totalTypes: types.length,
    legendaryCount,
    avgCatchRate,
    heaviest: { name: heaviest.name, weight: heaviest.weight },
    tallest: { name: tallest.name, height: tallest.height },
    typeDistribution
  };
}

