 * @param {Object[]} characters - Array of character objects
 * @returns {Object[]} Array of { name, credits } sorted by credits descending
 */
function richestCharacters(characters) {

}

exercises.solution:
function richestCharacters(characters) {
  return characters.map(c => ({ name: c.name, credits: c.credits }))
    .sort((a, b) => b.credits - a.credits);
}

