/**
 * @param {Object[]} planets - Array of planet objects
 * @param {Object[]} characters - Array of character objects
 * @returns {Object[]} Array of { name, homeworld } objects
 */
function getHomeworlds(planets, characters) {

}

exercises.solution:
function getHomeworlds(planets, characters) {
  return characters.map(c => ({
    name: c.name,
    homeworld: planets.find(p => p.id === c.homeworldId).name
  }));
}

