/**
 * @param {Object[]} characters - Array of character objects
 * @returns {Object[]} Force users sorted by forceRating descending
 */
function forceUsersRanked(characters) {

}

exercises.solution:
function forceUsersRanked(characters) {
  return characters
    .filter(c => c.forceRating > 0)
    .map(c => ({ name: c.name, forceRating: c.forceRating, rank: c.rank }))
    .sort((a, b) => b.forceRating - a.forceRating);
}

