exercises.solution:
function desertDwellers(planets, characters) {
  const desertPlanetIds = planets.filter(p => p.climate === 'arid').map(p => p.id);
  return characters
    .filter(c => desertPlanetIds.includes(c.homeworldId))
    .map(c => c.name)
    .sort();
}

