/**
 * @param {Object[]} characters - Array of character objects
 * @param {string} name1 - First character name
 * @param {string} name2 - Second character name
 * @returns {number[]} Sorted array of shared film episode numbers
 */
function sharedFilms(characters, name1, name2) {

}

exercises.solution:
function sharedFilms(characters, name1, name2) {
  const c1 = characters.find(c => c.name === name1);
  const c2 = characters.find(c => c.name === name2);
  if (!c1 || !c2) return [];
  return c1.films.filter(f => c2.films.includes(f)).sort((a, b) => a - b);
}

