exercises.solution:
function factionReport(planets, characters) {
  const result = {};
  characters.forEach(c => {
    if (!result[c.faction]) result[c.faction] = { names: [], forceSum: 0, totalCredits: 0, homeworldIds: new Set() };
    result[c.faction].names.push(c.name);
    result[c.faction].forceSum += c.forceRating;
    result[c.faction].totalCredits += c.credits;
    result[c.faction].homeworldIds.add(c.homeworldId);
  });
  const report = {};
  Object.entries(result).forEach(([faction, data]) => {
    report[faction] = {
      members: data.names.sort(),
      avgForceRating: Math.round(data.forceSum / data.names.length * 10) / 10,
      totalCredits: data.totalCredits,
      homeworlds: [...data.homeworldIds].map(id => planets.find(p => p.id === id).name).sort()
    };
  });
  return report;
}

