function planetCensus(planets, characters) {
  return planets.map(p => {
    const residents = characters.filter(c => c.homeworldId === p.id);
    return {
      name: p.name,
      climate: p.climate,
      residents: residents.map(c => c.name).sort(),
      residentCount: residents.length,
      avgForceRating: residents.length > 0 ? Math.round(residents.reduce((s, c) => s + c.forceRating, 0) / residents.length * 10) / 10 : 0,
      totalCredits: residents.reduce((s, c) => s + c.credits, 0)
    };
  }).sort((a, b) => b.residentCount - a.residentCount);
}

