exercises.solution:
function getTopScorers(players, n) {
  return [...players]
    .sort((a, b) => b.stats.ppg - a.stats.ppg)
    .slice(0, n)
    .map(p => ({ name: p.name, ppg: p.stats.ppg }));
}

