exercises.solution:
function getTeamRoster(players, teams, teamId) {
  const team = teams.find(t => t.id === teamId);
  const roster = players.filter(p => p.teamId === teamId).map(p => p.name).sort();
  return { team: team.name, players: roster, count: roster.length };
}

