exercises.solution:
function getPlayersByConference(players, teams, conference) {
  const confTeamIds = teams.filter(t => t.conference === conference).map(t => t.id);
  return players.filter(p => confTeamIds.includes(p.teamId)).map(p => p.name).sort();
}

