exercises.solution:
function getBestRecords(seasons, teams, year) {
  const season = seasons.find(s => s.year === year);
  return [...season.teamRecords]
    .sort((a, b) => b.wins - a.wins)
    .slice(0, 3)
    .map(r => ({
      team: teams.find(t => t.id === r.teamId).name,
      wins: r.wins,
      losses: r.losses
    }));
}

