exercises.solution:
function buildSeasonSummary(players, teams, seasons) {
  return seasons.map(s => {
    const sorted = [...s.teamRecords].sort((a, b) => b.wins - a.wins);
    const best = sorted[0];
    const worst = sorted[sorted.length - 1];
    return {
      year: s.year,
      mvp: players.find(p => p.id === s.mvpId).name,
      champion: teams.find(t => t.id === s.championId).name,
      bestRecord: { team: teams.find(t => t.id === best.teamId).name, wins: best.wins, losses: best.losses },
      worstRecord: { team: teams.find(t => t.id === worst.teamId).name, wins: worst.wins, losses: worst.losses }
    };
  });
}

