exercises.solution:
function leagueDatabase(players, teams, seasons) {
  const highestPaid = players.reduce((h, p) => p.salary > h.salary ? p : h);
  const topScorer = players.reduce((t, p) => p.stats.ppg > t.stats.ppg ? p : t);
  const avgSalary = Math.round(players.reduce((sum, p) => sum + p.salary, 0) / players.length);
  const positionBreakdown = {};
  players.forEach(p => { positionBreakdown[p.position] = (positionBreakdown[p.position] || 0) + 1; });
  const dynastyTeam = teams.reduce((d, t) => t.championships > d.championships ? t : d);
  return {
    totalPlayers: players.length,
    totalTeams: teams.length,
    totalSeasons: seasons.length,
    highestPaid: { name: highestPaid.name, salary: highestPaid.salary },
    topScorer: { name: topScorer.name, ppg: topScorer.stats.ppg },
    avgSalary,
    positionBreakdown,
    dynastyTeam: { name: dynastyTeam.name, championships: dynastyTeam.championships }
  };
}

