exercises.solution:
function getTopMovieStars(heroes, n) {
  return [...heroes]
    .sort((a, b) => b.movies - a.movies)
    .slice(0, n)
    .map(h => ({ name: h.name, alias: h.alias, movies: h.movies }));
}

