exercises.solution:
function getTeamRoster(heroes, teams, teamId) {
  const team = teams.find(t => t.id === teamId);
  const members = heroes.filter(h => h.teamIds.includes(teamId)).map(h => h.name).sort();
  return { team: team.name, members, count: members.length };
}

