exercises.solution:
function getHeroTeams(heroes, teams, heroId) {
  const hero = heroes.find(h => h.id === heroId);
  const teamNames = hero.teamIds.map(id => teams.find(t => t.id === id).name).sort();
  return { hero: hero.name, alias: hero.alias, teams: teamNames };
}

