exercises.solution:
function getMultiTeamHeroes(heroes) {
  return heroes
    .filter(h => h.teamIds.length > 1)
    .map(h => ({ name: h.name, alias: h.alias, teamCount: h.teamIds.length }))
    .sort((a, b) => b.teamCount - a.teamCount);
}

