exercises.solution:
function getTeamAverageStats(heroes, teams, teamId) {
  const team = teams.find(t => t.id === teamId);
  const members = heroes.filter(h => h.teamIds.includes(teamId));
  const avg = (arr, key) => Math.round(arr.reduce((s, h) => s + h.stats[key], 0) / arr.length * 10) / 10;
  return {
    team: team.name,
    avgStrength: avg(members, 'strength'),
    avgSpeed: avg(members, 'speed'),
    avgIntelligence: avg(members, 'intelligence'),
    avgDurability: avg(members, 'durability')
  };
}

