exercises.solution:
function getHeroesByTeamType(heroes, teams, type) {
  const typeTeamIds = teams.filter(t => t.type === type).map(t => t.id);
  const names = heroes
    .filter(h => h.teamIds.some(id => typeTeamIds.includes(id)))
    .map(h => h.name);
  return [...new Set(names)].sort();
}

