exercises.solution:
function getMostPowerful(heroes, n) {
  return [...heroes]
    .map(h => ({
      name: h.name,
      alias: h.alias,
      totalPower: h.stats.strength + h.stats.speed + h.stats.intelligence + h.stats.durability
    }))
    .sort((a, b) => b.totalPower - a.totalPower)
    .slice(0, n);
}

