exercises.solution:
function powerCensus(heroes) {
  const counts = {};
  heroes.forEach(h => {
    h.powers.forEach(p => { counts[p] = (counts[p] || 0) + 1; });
  });
  return Object.entries(counts)
    .map(([power, count]) => ({ power, count }))
    .sort((a, b) => b.count - a.count || a.power.localeCompare(b.power));
}

