exercises.solution:
function originAnalysis(heroes) {
  const result = {};
  heroes.forEach(h => {
    if (!result[h.origin]) result[h.origin] = { members: [] };
    result[h.origin].members.push(h);
  });
  Object.entries(result).forEach(([origin, data]) => {
    const m = data.members;
    result[origin] = {
      count: m.length,
      heroes: m.map(h => h.name).sort(),
      avgMovies: Math.round(m.reduce((s, h) => s + h.movies, 0) / m.length * 10) / 10,
      avgPower: Math.round(m.reduce((s, h) => s + h.stats.strength + h.stats.speed + h.stats.intelligence + h.stats.durability, 0) / m.length * 10) / 10
    };
  });
  return result;
}

