exercises.solution:
function mcuDatabase(heroes, teams) {
  const mostMovies = heroes.reduce((m, h) => h.movies > m.movies ? h : m);
  const withPower = heroes.map(h => ({ ...h, totalPower: h.stats.strength + h.stats.speed + h.stats.intelligence + h.stats.durability }));
  const mostPowerful = withPower.reduce((m, h) => h.totalPower > m.totalPower ? h : m);
  const teamBreakdown = {};
  teams.forEach(t => { teamBreakdown[t.name] = heroes.filter(h => h.teamIds.includes(t.id)).length; });
  const originBreakdown = {};
  heroes.forEach(h => { originBreakdown[h.origin] = (originBreakdown[h.origin] || 0) + 1; });
  return {
    totalHeroes: heroes.length,
    totalTeams: teams.length,
    activeHeroes: heroes.filter(h => h.isActive).length,
    mostMovies: { name: mostMovies.name, alias: mostMovies.alias, movies: mostMovies.movies },
    mostPowerful: { name: mostPowerful.name, alias: mostPowerful.alias, totalPower: mostPowerful.totalPower },
    avgMovies: Math.round(heroes.reduce((s, h) => s + h.movies, 0) / heroes.length * 10) / 10,
    teamBreakdown,
    originBreakdown
  };
}

