exercises.solution:
function getInventory(characters, equipment, characterId) {
  const char = characters.find(c => c.id === characterId);
  const items = equipment.filter(e => char.equipmentIds.includes(e.id));
  return {
    character: char.name,
    items: items.map(e => e.name).sort(),
    totalValue: items.reduce((sum, e) => sum + e.value, 0)
  };
}

