exercises.solution:
function getEquipmentByRarity(equipment, rarity) {
  const items = equipment.filter(e => e.rarity === rarity);
  return {
    rarity,
    items: items.map(e => e.name).sort(),
    count: items.length,
    totalValue: items.reduce((sum, e) => sum + e.value, 0)
  };
}

