exercises.solution:
function getSharedSpells(characters, spells, charId1, charId2) {
  const char1 = characters.find(c => c.id === charId1);
  const char2 = characters.find(c => c.id === charId2);
  const shared = char1.spellIds.filter(id => char2.spellIds.includes(id));
  return spells.filter(s => shared.includes(s.id)).map(s => s.name).sort();
}

