function getPartyGold(characters, className) {
  const members = characters.filter(c => c.class === className);
  const totalGold = members.reduce((sum, c) => sum + c.gold, 0);
  return {
    class: className,
    members: members.map(c => c.name).sort(),
    totalGold,
    avgGold: members.length > 0 ? Math.round(totalGold / members.length) : 0
  };
}

