function buildCharacterSheet(characters, spells, equipment, characterId) {
  const char = characters.find(c => c.id === characterId);
  const charSpells = spells.filter(s => char.spellIds.includes(s.id)).map(s => s.name).sort();
  const charEquip = equipment.filter(e => char.equipmentIds.includes(e.id));
  const inventoryValue = charEquip.reduce((sum, e) => sum + e.value, 0);
  const totalStats = Object.values(char.stats).reduce((sum, v) => sum + v, 0);
  return {
    name: char.name,
    race: char.race,
    class: char.class,
    level: char.level,
    hp: char.hp,
    ac: char.ac,
    alignment: char.alignment,
    totalStats,
    spells: charSpells,
    equipment: charEquip.map(e => e.name).sort(),
    inventoryValue,
    netWorth: char.gold + inventoryValue
  };
}

