function getSpellPopularity(characters, spells) {
  return spells.map(s => {
    const casters = characters.filter(c => c.spellIds.includes(s.id));
    return {
      name: s.name,
      level: s.level,
      school: s.school,
      knownBy: casters.length,
      casters: casters.map(c => c.name).sort()
    };
  }).sort((a, b) => b.knownBy - a.knownBy || a.name.localeCompare(b.name));
}

