function buildClassReport(characters, spells, equipment) {
  const classes = [...new Set(characters.map(c => c.class))].sort();
  return classes.map(cls => {
    const members = characters.filter(c => c.class === cls);
    const allSpellIds = [...new Set(members.flatMap(c => c.spellIds))];
    const allEquipIds = members.flatMap(c => c.equipmentIds);
    const totalEquipVal = allEquipIds.reduce((sum, id) => {
      const item = equipment.find(e => e.id === id);
      return sum + (item ? item.value : 0);
    }, 0);
    return {
      class: cls,
      members: members.map(c => c.name).sort(),
      count: members.length,
      avgLevel: Math.round(members.reduce((s, c) => s + c.level, 0) / members.length * 10) / 10,
      totalHp: members.reduce((s, c) => s + c.hp, 0),
      uniqueSpells: allSpellIds.length,
      totalEquipmentValue: totalEquipVal
    };
  });
}

