  const mostSpellsChar = [...characters].sort((a, b) => b.spellIds.length - a.spellIds.length)[0];
  const mostExpItem = [...equipment].sort((a, b) => b.value - a.value)[0];
  const schoolBreakdown = spells.reduce((acc, s) => { acc[s.school] = (acc[s.school] || 0) + 1; return acc; }, {});
  const rarityBreakdown = equipment.reduce((acc, e) => { acc[e.rarity] = (acc[e.rarity] || 0) + 1; return acc; }, {});
  const totalEquipValue = characters.reduce((sum, c) => {
    return sum + c.equipmentIds.reduce((s, id) => {
      const item = equipment.find(e => e.id === id);
      return s + (item ? item.value : 0);
    }, 0);
  }, 0);
  return {
    totalCharacters: characters.length,
    livingCharacters: characters.filter(c => c.isAlive).length,
    averageLevel: Math.round(characters.reduce((s, c) => s + c.level, 0) / characters.length * 10) / 10,
    totalPartyGold: characters.reduce((s, c) => s + c.gold, 0),
    richestCharacter: richest.name,
    mostSpells: { name: mostSpellsChar.name, count: mostSpellsChar.spellIds.length },
    mostExpensive: { name: mostExpItem.name, value: mostExpItem.value },
    schoolBreakdown,
    rarityBreakdown,
    totalCampaignValue: characters.reduce((s, c) => s + c.gold, 0) + totalEquipValue
  };
}

